// ============================================
// EMBEDDING VALIDATION DEBUG NODE
// ============================================
// Zweck: Validiere Embedding-Dimensionen bevor sie zu Pinecone gesendet werden
// Füge diesen Node zwischen "Embeddings" und "Insert Pinecone" ein

const EXPECTED_DIMENSION = 768; // Für text-embedding-004
// const EXPECTED_DIMENSION = 3072; // Für gemini-embedding-001

const items = $input.all();

console.log('\n=== EMBEDDING VALIDATION START ===');
console.log(`Anzahl Items: ${items.length}`);
console.log(`Erwartete Dimension: ${EXPECTED_DIMENSION}`);

const validatedItems = [];
const errors = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const itemLog = `Item ${i + 1}/${items.length}`;

  console.log(`\n--- ${itemLog} ---`);

  try {
    // Extrahiere Embedding aus verschiedenen möglichen Strukturen
    let embedding = null;

    // Versuche verschiedene Pfade
    if (item.json?.embedding) {
      embedding = item.json.embedding;
      console.log('✓ Embedding gefunden in: item.json.embedding');
    } else if (Array.isArray(item.json)) {
      embedding = item.json;
      console.log('✓ Embedding gefunden in: item.json (Array)');
    } else if (item.json?.data?.embedding) {
      embedding = item.json.data.embedding;
      console.log('✓ Embedding gefunden in: item.json.data.embedding');
    } else if (item.json?.values) {
      embedding = item.json.values;
      console.log('✓ Embedding gefunden in: item.json.values');
    } else {
      console.log('❌ Embedding Struktur:');
      console.log(JSON.stringify(item.json, null, 2).substring(0, 500));
      throw new Error(`Embedding nicht gefunden in Item ${i + 1}`);
    }

    // Validiere dass Embedding ein Array ist
    if (!Array.isArray(embedding)) {
      throw new Error(`Embedding ist kein Array (Type: ${typeof embedding})`);
    }

    // Validiere Dimension
    const dimension = embedding.length;
    console.log(`Dimension: ${dimension}`);

    if (dimension === 0) {
      throw new Error('❌ KRITISCHER FEHLER: Embedding hat Dimension 0!');
    }

    if (dimension !== EXPECTED_DIMENSION) {
      const warning = `⚠️ WARNUNG: Dimension ${dimension} weicht ab von erwartet ${EXPECTED_DIMENSION}`;
      console.log(warning);
      errors.push(`${itemLog}: ${warning}`);
    }

    // Validiere dass Werte numerisch sind
    const nonNumeric = embedding.filter(v => typeof v !== 'number');
    if (nonNumeric.length > 0) {
      throw new Error(`Embedding enthält ${nonNumeric.length} nicht-numerische Werte`);
    }

    // Validiere Wertebereich (typisch -1 bis 1 für normalisierte Embeddings)
    const outOfRange = embedding.filter(v => Math.abs(v) > 10);
    if (outOfRange.length > 0) {
      console.log(`⚠️ ${outOfRange.length} Werte außerhalb typischem Bereich [-10, 10]`);
    }

    // Sample der ersten Werte
    console.log('Erste 5 Werte:', embedding.slice(0, 5).map(v => v.toFixed(4)));
    console.log('Letzte 5 Werte:', embedding.slice(-5).map(v => v.toFixed(4)));

    // Berechne Statistiken
    const sum = embedding.reduce((a, b) => a + b, 0);
    const mean = sum / dimension;
    const magnitude = Math.sqrt(embedding.reduce((a, b) => a + b * b, 0));

    console.log(`Mittelwert: ${mean.toFixed(6)}`);
    console.log(`Magnitude: ${magnitude.toFixed(6)}`);

    // Validiere dass Embedding nicht nur Nullen ist
    const allZeros = embedding.every(v => v === 0);
    if (allZeros) {
      throw new Error('❌ Embedding besteht nur aus Nullen!');
    }

    console.log('✅ Validation erfolgreich');
    validatedItems.push(item);

  } catch (error) {
    const errorMsg = `${itemLog}: ${error.message}`;
    console.error('❌ Fehler:', errorMsg);
    errors.push(errorMsg);
  }
}

console.log('\n=== VALIDATION SUMMARY ===');
console.log(`Erfolgreich validiert: ${validatedItems.length}/${items.length}`);
console.log(`Fehler: ${errors.length}`);

if (errors.length > 0) {
  console.error('\n=== FEHLER-DETAILS ===');
  errors.forEach(err => console.error(err));

  // Workflow stoppen bei kritischen Fehlern
  throw new Error(
    `Embedding Validation fehlgeschlagen!\n` +
    `Erfolgreich: ${validatedItems.length}/${items.length}\n` +
    `Fehler: ${errors.join('; ')}`
  );
}

console.log('✅ ALLE EMBEDDINGS VALIDIERT');
console.log('=== EMBEDDING VALIDATION END ===\n');

// Gebe validierte Items weiter
return validatedItems;
